/bin/bash -lc "cat > src/styles.css <<'EOF'
/* The complete accent palette is defined at the semantic theme layer. */
.g-root_theme_light {
  --g-color-base-brand: #7755d9;
  --g-color-base-brand-hover: #6846ca;
  --g-color-base-selection: #f0ebfc;
  --g-color-base-selection-hover: #e8e0fa;
  --g-color-line-brand: #7755d9;
  --g-color-text-brand: #7652d4;
  --g-color-text-brand-contrast: #ffffff;
  --g-color-text-link: #7652d4;
  --g-color-text-link-hover: #5f3abf;
  --g-color-base-background: #ffffff;
  --g-color-base-generic-ultralight: #f7f8fa;
  --g-color-line-generic: #eaecef;
  --g-color-text-primary: #292b35;
  --g-color-text-secondary: #858892;
  --g-color-text-hint: #a4a6af;
  --app-surface-soft: #fafafb;
  --app-green-soft: #eaf7ef;
  --app-green-text: #329769;
  --app-orange-soft: #fff5e9;
  --app-orange-text: #c78b37;
  --app-blue-soft: #edf3ff;
  --app-blue-text: #5d87cd;
  --app-pink-soft: #fcedf3;
  --app-pink-text: #bb6c92;
}
.g-root_theme_dark {
  --g-color-base-brand: #a489ee;
  --g-color-base-brand-hover: #b69ef3;
  --g-color-base-selection: #352c4d;
  --g-color-base-selection-hover: #42345e;
  --g-color-line-brand: #a489ee;
  --g-color-text-brand: #bda6f3;
  --g-color-text-brand-contrast: #201631;
  --g-color-text-link: #bda6f3;
  --g-color-text-link-hover: #d3c3f8;
  --app-surface-soft: #25252b;
  --app-green-soft: #203a30;
  --app-green-text: #7cc9a2;
  --app-orange-soft: #3e3325;
  --app-orange-text: #d9b16c;
  --app-blue-soft: #28334b;
  --app-blue-text: #92b3ec;
  --app-pink-soft: #422c3a;
  --app-pink-text: #db9cbd;
}
:root {
  font-synthesis: none;
  --g-font-family-sans: 'Inter', 'Arial', sans-serif;
  --g-font-family-sans: 'Inter', 'Helvetica Neue', 'Arial', sans-serif;
  --g-text-body-font-family: var(--g-font-family-sans);
  --g-text-header-font-family: var(--g-font-family-sans);
  --g-text-display-font-family: var(--g-font-family-sans);
  --g-text-subheader-font-family: var(--g-font-family-sans);
  --g-border-radius-s: 5px;
  --g-border-radius-m: 8px;
  --g-border-radius-l: 12px;
  --g-border-radius-xl: 16px;
}
* {box-sizing: border-box;}
body {margin: 0; color: var(--g-color-text-primary); -webkit-font-smoothing: antialiased;}
body, #root {min-width: 360px; min-height: 100vh;}
button, input {font: inherit;}
.app-shell {height: 100vh; --gn-aside-header-padding-top: var(--g-spacing-3); --gn-aside-header-background-color: var(--g-color-base-background); --gn-aside-header-item-current-background-color: var(--g-color-base-selection); --gn-aside-header-item-current-text-color: var(--g-color-text-brand); --gn-aside-header-item-current-icon-color: var(--g-color-text-brand); --gn-aside-header-item-current-background-color-hover: var(--g-color-base-selection-hover); --gn-aside-header-item-icon-color: var(--g-color-text-secondary); --gn-aside-header-item-text-color: var(--g-color-text-primary); --gn-aside-header-item-expanded-radius: var(--g-border-radius-m);}
.app-logo {font-weight: 750; letter-spacing: -1.4px;}
.brand-mark {display: inline-grid; grid-template-columns: repeat(2, 11px); grid-template-rows: repeat(2, 11px); gap: 3px; width: 26px; height: 26px; transform: rotate(-9deg);}
.brand-mark span {background: var(--g-color-base-brand); border-radius: var(--g-border-radius-xs);}
.brand-mark span:nth-child(2) {opacity: .5;}
.brand-mark span:nth-child(3) {opacity: .75;}
.sidebar-intro {padding: var(--g-spacing-6) var(--g-spacing-4) var(--g-spacing-3);}
.sidebar-intro.compact {padding: var(--g-spacing-6) 0 var(--g-spacing-1);}
.workspace-switch {height: 62px; --g-button-border-color: var(--g-color-line-generic); --g-button-border-radius: var(--g-border-radius-m);}
.shop-avatar {display: inline-flex; width: 32px; height: 32px; flex-shrink: 0; justify-content: center; align-items: center; color: var(--g-color-text-brand); background: var(--g-color-base-selection); border-radius: var(--g-border-radius-m);}
.shop-info {display: inline-flex; flex-direction: column; align-items: flex-start; gap: var(--g-spacing-1); flex: 1; min-width: 0; margin: 0 var(--g-spacing-2); text-align: left;}
.shop-info strong {font-size: 12px; font-weight: 550; max-width: 120px; overflow: hidden; text-overflow: ellipsis;}
.shop-info small {color: var(--g-color-text-secondary); font-size: 10px; font-weight: 400;}
.nav-caption {display: block; font-size: 9px; letter-spacing: 1.1px; color: var(--g-color-text-hint); margin-top: var(--g-spacing-8); padding-left: var(--g-spacing-2);}
.nav-item {font-size: 13px; margin-bottom: var(--g-spacing-2);}
.nav-count {font-size: 10px; font-weight: 600; padding: var(--g-spacing-1) var(--g-spacing-2); background: var(--g-color-base-background); border-radius: var(--g-border-radius-s); color: var(--g-color-text-brand);}
.sidebar-footer {padding: var(--g-spacing-2);}
.help-card {background: var(--app-surface-soft); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); padding: var(--g-spacing-4); margin-bottom: var(--g-spacing-6);}
.help-card-icon {display: block; color: var(--g-color-text-secondary); margin-bottom: var(--g-spacing-3);}
.help-card strong {font-size: 12px; font-weight: 600;}
.help-card p {color: var(--g-color-text-secondary); font-size: 11px; line-height: 1.7; margin: var(--g-spacing-2) 0 var(--g-spacing-4);}
.help-card .g-button {font-size: 10px; --g-button-background-color: var(--g-color-base-background);}
.sidebar-help {color: var(--g-color-text-secondary); font-size: 11px; margin-bottom: var(--g-spacing-4); text-align: left;}
.sidebar-account {display: flex; gap: var(--g-spacing-2); align-items: center; border-top: 1px solid var(--g-color-line-generic); padding: var(--g-spacing-4) 0 var(--g-spacing-1);}
.account-avatar, .top-avatar {display: grid; place-items: center; border-radius: 50%; background: var(--g-color-base-selection); color: var(--g-color-text-brand); font-weight: 600; font-size: 11px; flex-shrink: 0;}
.account-avatar {width: 33px; height: 33px;}
.sidebar-account strong, .sidebar-account small {display: block;}
.sidebar-account strong {font-weight: 550; font-size: 10px;}
.sidebar-account small {font-size: 10px; margin-top: var(--g-spacing-1); color: var(--g-color-text-secondary);}
.sidebar-footer.compact {padding: 0;}
.compact .sidebar-account {justify-content: center;}
.workspace {height: 100vh; min-width: 0; display: flex; flex-direction: column; background: var(--g-color-base-generic-ultralight);}
.topbar {height: 69px; padding: 0 var(--g-spacing-8); display: flex; justify-content: space-between; align-items: center; background: var(--g-color-base-background); border-bottom: 1px solid var(--g-color-line-generic); flex-shrink: 0;}
