.support-icon {display: grid; place-items: center; width: 64px; height: 64px; border-radius: 50%; background: var(--g-color-base-selection); color: var(--g-color-text-brand);}
.support-content p {color: var(--g-color-text-secondary); line-height: 1.8; font-size: 12px; margin: 0;}
.support-content small {color: var(--g-color-text-hint); font-size: 10px;}
.notification-entry {display: flex; gap: var(--g-spacing-4); padding: var(--g-spacing-4) 0; border-bottom: 1px solid var(--g-color-line-generic);}
.notification-entry:last-child {border: none;}
.notification-entry strong {font-size: 12px; font-weight: 550;}
.notification-entry p, .notification-entry small {color: var(--g-color-text-secondary); font-size: 11px;}
.notification-entry .g-button {font-size: 11px; --g-button-padding: 0; color: var(--g-color-text-brand);}
.users-panel, .settings-panel {background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); padding: var(--g-spacing-6);}
.user-list-row {display: flex; align-items: center; gap: var(--g-spacing-5); padding: var(--g-spacing-4) 0; border-bottom: 1px solid var(--g-color-line-generic); font-size: 12px;}
.user-list-row>.customer {flex: 1;}
.user-list-row>span {color: var(--g-color-text-secondary);}
.user-list-row>strong {font-weight: 550; min-width: 100px;}
.settings-panel {max-width: 550px; display: flex; flex-direction: column; gap: var(--g-spacing-5);}
.settings-panel p {font-size: 12px; color: var(--g-color-text-secondary); margin: 0;}
.settings-panel>.g-button {align-self: flex-start;}
@media (min-width: 1550px) {
  .main-content {padding-left: var(--g-spacing-10); padding-right: var(--g-spacing-10);}
  .stat-card {padding: var(--g-spacing-5) var(--g-spacing-6);}
  .table-scroll {max-height: 590px;}
}
@media (max-width: 1200px) {
  .main-content {padding-left: var(--g-spacing-5); padding-right: var(--g-spacing-5);}
  .stat-card {padding: var(--g-spacing-4);}
  .stat-bottom {font-size: 8px; gap: var(--g-spacing-1); flex-wrap: wrap;}
  .stat-value.g-text {font-size: 24px;}
  .table-toolbar {gap: var(--g-spacing-2); padding-left: var(--g-spacing-4); padding-right: var(--g-spacing-4);}
  .order-search {max-width: 36%;}
  .toolbar-actions {gap: var(--g-spacing-1);}
  .panel-description {display: none;}
  .status-tabs {gap: var(--g-spacing-4);}
  .page-badge {display: none;}
}
@media (max-width: 800px) {
  .topbar {padding: 0 var(--g-spacing-5); height: 58px;}
  .main-content {padding-top: var(--g-spacing-5);}
  .stats-grid {grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--g-spacing-3);}
  .stat-card-top {font-size: 11px;}
  .stat-value.g-text {font-size: 25px;}
  .stat-bottom {font-size: 9px;}
  .page-heading {align-items: flex-start; flex-wrap: wrap; margin-bottom: var(--g-spacing-5);}
  .heading-actions {margin-top: var(--g-spacing-1);}
  .table-toolbar {flex-wrap: wrap;}
  .order-search {width: 100%; max-width: none;}
  .toolbar-actions {width: 100%; justify-content: space-between; margin-top: var(--g-spacing-1);}
  .table-scroll {max-height: 500px;}
  .under-table>span:last-child {display: none;}
  .table-footer {flex-wrap: wrap; gap: var(--g-spacing-3);}
  .page-footer {align-items: flex-start; flex-direction: column; gap: var(--g-spacing-1);}
  .live-label, .live-dot {display: none;}
  .topbar-divider {margin: 0 var(--g-spacing-1);}
  .user-list-row {flex-wrap: wrap;}
}
@media (max-width: 480px) {
  .main-content {padding: var(--g-spacing-4) var(--g-spacing-3) 0;}
  .topbar {padding: 0 var(--g-spacing-3);}
  .breadcrumbs {gap: var(--g-spacing-1); font-size: 10px;}
  .breadcrumbs>span {max-width: 112px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;}
  .top-avatar {margin-left: 0; width: 25px; height: 25px; font-size: 9px;}
  .topbar-right {gap: 0;}
  .heading-line .g-text {font-size: 25px;}
  .page-heading p {font-size: 10px; line-height: 1.6;}
  .heading-actions {width: 100%;}
  .heading-actions .g-button {flex: 1; font-size: 10px;}
  .stat-card {padding: var(--g-spacing-3);}
  .stat-icon {width: 25px; height: 25px;}
  .stat-card-top {font-size: 9px; gap: 2px;}
  .stat-icon svg {width: 15px; height: 15px;}
  .stat-value.g-text {font-size: 22px; line-height: 28px;}
  .stat-bottom {font-size: 8px; white-space: normal;}
  .overview-caption {font-size: 10px;}
  .overview-caption>span:last-child {font-size: 8px; gap: var(--g-spacing-1);}
  .status-tabs {padding: 0 var(--g-spacing-3);}
  .table-toolbar {padding: var(--g-spacing-3);}
  .toolbar-actions .g-button {font-size: 9px; --g-button-padding: 6px;}
  .toolbar-separator {display: none;}
  .group-label {display: none;}
  .table-footer {padding: var(--g-spacing-3);}
  .per-page-label {display: none;}
  .pagination-divider {margin: 0 var(--g-spacing-1);}
  .under-table>span {font-size: 8px; line-height: 1.5;}
  .selection-bar {gap: var(--g-spacing-1); padding: var(--g-spacing-2); flex-wrap: wrap;}
  .selection-bar strong {font-size: 10px;}
}
@media (prefers-reduced-motion: reduce) {*, *::before, *::after {scroll-behavior: auto "'!important; transition: none !important; animation: none !important;}}
EOF
npm run build'

item.command:
/bin/bash -lc "cat > src/styles.css <<'EOF'
/* The complete accent palette is defined at the semantic theme layer. */
.g-root_theme_light {
  --g-color-base-brand: #7755d9;
  --g-color-base-brand-hover: #6846ca;
  --g-color-base-selection: #f0ebfc;
  --g-color-base-selection-hover: #e8e0fa;
  --g-color-line-brand: #7755d9;
  --g-color-text-brand: #7652d4;
  --g-color-text-brand-contrast: #ffffff;
  --g-color-text-link: #7652d4;
  --g-color-text-link-hover: #5f3abf;
  --g-color-base-background: #ffffff;
  --g-color-base-generic-ultralight: #f7f8fa;
  --g-color-line-generic: #eaecef;
  --g-color-text-primary: #292b35;
  --g-color-text-secondary: #858892;
  --g-color-text-hint: #a4a6af;
  --app-surface-soft: #fafafb;
  --app-green-soft: #eaf7ef;
  --app-green-text: #329769;
  --app-orange-soft: #fff5e9;
  --app-orange-text: #c78b37;
  --app-blue-soft: #edf3ff;
  --app-blue-text: #5d87cd;
  --app-pink-soft: #fcedf3;
  --app-pink-text: #bb6c92;
}
.g-root_theme_dark {
  --g-color-base-brand: #a489ee;
  --g-color-base-brand-hover: #b69ef3;
  --g-color-base-selection: #352c4d;
  --g-color-base-selection-hover: #42345e;
  --g-color-line-brand: #a489ee;
  --g-color-text-brand: #bda6f3;
  --g-color-text-brand-contrast: #201631;
  --g-color-text-link: #bda6f3;
  --g-color-text-link-hover: #d3c3f8;
  --app-surface-soft: #25252b;
  --app-green-soft: #203a30;
  --app-green-text: #7cc9a2;
  --app-orange-soft: #3e3325;
  --app-orange-text: #d9b16c;
  --app-blue-soft: #28334b;
  --app-blue-text: #92b3ec;
  --app-pink-soft: #422c3a;
  --app-pink-text: #db9cbd;
}
:root {
  font-synthesis: none;
  --g-font-family-sans: 'Inter', 'Arial', sans-serif;
  --g-font-family-sans: 'Inter', 'Helvetica Neue', 'Arial', sans-serif;
  --g-text-body-font-family: var(--g-font-family-sans);
  --g-text-header-font-family: var(--g-font-family-sans);
  --g-text-display-font-family: var(--g-font-family-sans);
  --g-text-subheader-font-family: var(--g-font-family-sans);
  --g-border-radius-s: 5px;
  --g-border-radius-m: 8px;
  --g-border-radius-l: 12px;
  --g-border-radius-xl: 16px;
}
* {box-sizing: border-box;}
body {margin: 0; color: var(--g-color-text-primary); -webkit-font-smoothing: antialiased;}
body, #root {min-width: 360px; min-height: 100vh;}
button, input {font: inherit;}
.app-shell {height: 100vh; --gn-aside-header-padding-top: var(--g-spacing-3); --gn-aside-header-background-color: var(--g-color-base-background); --gn-aside-header-item-current-background-color: var(--g-color-base-selection); --gn-aside-header-item-current-text-color: var(--g-color-text-brand); --gn-aside-header-item-current-icon-color: var(--g-color-text-brand); --gn-aside-header-item-current-background-color-hover: var(--g-color-base-selection-hover); --gn-aside-header-item-icon-color: var(--g-color-text-secondary); --gn-aside-header-item-text-color: var(--g-color-text-primary); --gn-aside-header-item-expanded-radius: var(--g-border-radius-m);}
.app-logo {font-weight: 750; letter-spacing: -1.4px;}
.brand-mark {display: inline-grid; grid-template-columns: repeat(2, 11px); grid-template-rows: repeat(2, 11px); gap: 3px; width: 26px; height: 26px; transform: rotate(-9deg);}
.brand-mark span {background: var(--g-color-base-brand); border-radius: var(--g-border-radius-xs);}
.brand-mark span:nth-child(2) {opacity: .5;}
.brand-mark span:nth-child(3) {opacity: .75;}
.sidebar-intro {padding: var(--g-spacing-6) var(--g-spacing-4) var(--g-spacing-3);}
.sidebar-intro.compact {padding: var(--g-spacing-6) 0 var(--g-spacing-1);}
.workspace-switch {height: 62px; --g-button-border-color: var(--g-color-line-generic); --g-button-border-radius: var(--g-border-radius-m);}
.shop-avatar {display: inline-flex; width: 32px; height: 32px; flex-shrink: 0; justify-content: center; align-items: center; color: var(--g-color-text-brand); background: var(--g-color-base-selection); border-radius: var(--g-border-radius-m);}
.shop-info {display: inline-flex; flex-direction: column; align-items: flex-start; gap: var(--g-spacing-1); flex: 1; min-width: 0; margin: 0 var(--g-spacing-2); text-align: left;}
.shop-info strong {font-size: 12px; font-weight: 550; max-width: 120px; overflow: hidden; text-overflow: ellipsis;}
.shop-info small {color: var(--g-color-text-secondary); font-size: 10px; font-weight: 400;}
.nav-caption {display: block; font-size: 9px; letter-spacing: 1.1px; color: var(--g-color-text-hint); margin-top: var(--g-spacing-8); padding-left: var(--g-spacing-2);}
.nav-item {font-size: 13px; margin-bottom: var(--g-spacing-2);}
.nav-count {font-size: 10px; font-weight: 600; padding: var(--g-spacing-1) var(--g-spacing-2); background: var(--g-color-base-background); border-radius: var(--g-border-radius-s); color: var(--g-color-text-brand);}
.sidebar-footer {padding: var(--g-spacing-2);}
.help-card {background: var(--app-surface-soft); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); padding: var(--g-spacing-4); margin-bottom: var(--g-spacing-6);}
.help-card-icon {display: block; color: var(--g-color-text-secondary); margin-bottom: var(--g-spacing-3);}
.help-card strong {font-size: 12px; font-weight: 600;}
.help-card p {color: var(--g-color-text-secondary); font-size: 11px; line-height: 1.7; margin: var(--g-spacing-2) 0 var(--g-spacing-4);}
.help-card .g-button {font-size: 10px; --g-button-background-color: var(--g-color-base-background);}
.sidebar-help {color: var(--g-color-text-secondary); font-size: 11px; margin-bottom: var(--g-spacing-4); text-align: left;}
.sidebar-account {display: flex; gap: var(--g-spacing-2); align-items: center; border-top: 1px solid var(--g-color-line-generic); padding: var(--g-spacing-4) 0 var(--g-spacing-1);}
.account-avatar, .top-avatar {display: grid; place-items: center; border-radius: 50%; background: var(--g-color-base-selection); color: var(--g-color-text-brand); font-weight: 600; font-size: 11px; flex-shrink: 0;}
.account-avatar {width: 33px; height: 33px;}
.sidebar-account strong, .sidebar-account small {display: block;}
.sidebar-account strong {font-weight: 550; font-size: 10px;}
.sidebar-account small {font-size: 10px; margin-top: var(--g-spacing-1); color: var(--g-color-text-secondary);}
.sidebar-footer.compact {padding: 0;}
.compact .sidebar-account {justify-content: center;}
.workspace {height: 100vh; min-width: 0; display: flex; flex-direction: column; background: var(--g-color-base-generic-ultralight);}
.topbar {height: 69px; padding: 0 var(--g-spacing-8); display: flex; justify-content: space-between; align-items: center; background: var(--g-color-base-background); border-bottom: 1px solid var(--g-color-line-generic); flex-shrink: 0;}
.breadcrumbs {display: flex; align-items: center; gap: var(--g-spacing-3); font-size: 11px; color: var(--g-color-text-secondary);}
.breadcrumbs strong {font-weight: 500; color: var(--g-color-text-primary);}
.topbar-right {display: flex; align-items: center; gap: var(--g-spacing-2); font-size: 10px;}
.live-label {color: var(--g-color-text-secondary);}
.live-dot, .tiny-dot {width: 5px; height: 5px; border-radius: 50%; display: inline-block; background: var(--app-green-text); flex-shrink: 0;}
.topbar-divider {width: 1px; height: 19px; background: var(--g-color-line-generic); margin: 0 var(--g-spacing-3);}
.notification-button {position: relative; color: var(--g-color-text-secondary);}
.notification-button i {width: 4px; height: 4px; position: absolute; right: 7px; top: 4px; border-radius: 50%; background: var(--g-color-base-brand); border: 1px solid var(--g-color-base-background);}
.top-avatar {width: 30px; height: 30px; margin-left: var(--g-spacing-3);}
.main-content {padding: var(--g-spacing-7) var(--g-spacing-8) 0; flex: 1; min-height: 0; min-width: 0; overflow-y: auto;}
.page-heading {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); margin-bottom: var(--g-spacing-7);}
.heading-line {display: flex; align-items: center; gap: var(--g-spacing-3);}
.heading-line .g-text {font-size: 28px; line-height: 38px; letter-spacing: -.8px; font-weight: 650;}
.page-badge {font-size: 9px; padding: var(--g-spacing-1) var(--g-spacing-2); color: var(--g-color-text-secondary); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-s); background: var(--g-color-base-background); margin-top: var(--g-spacing-1);}
.page-heading p {font-size: 11px; color: var(--g-color-text-secondary); margin: var(--g-spacing-2) 0 0; line-height: 1.5;}
.heading-actions {display: flex; gap: var(--g-spacing-2); flex-shrink: 0;}
.heading-actions .g-button {font-size: 11px; --g-button-border-radius: var(--g-border-radius-m); height: 36px;}
.overview-caption {display: flex; align-items: center; justify-content: space-between; margin-bottom: var(--g-spacing-3); font-size: 11px;}
.overview-caption>span:first-child {font-weight: 550;}
.overview-caption>span:last-child {color: var(--g-color-text-hint); display: flex; align-items: center; gap: var(--g-spacing-2); font-size: 10px;}
.stats-grid {display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--g-spacing-4); margin-bottom: var(--g-spacing-6);}
.stat-card {padding: var(--g-spacing-4) var(--g-spacing-5); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); background: var(--g-color-base-background); box-shadow: 0 2px 3px var(--g-color-base-generic-ultralight); min-width: 0;}
.stat-card-top {display: flex; justify-content: space-between; align-items: center; gap: var(--g-spacing-2); margin-bottom: var(--g-spacing-2); color: var(--g-color-text-secondary); font-size: 11px;}
.stat-icon {width: 32px; height: 32px; display: inline-flex; align-items: center; justify-content: center; border-radius: var(--g-border-radius-m); flex-shrink: 0;}
.violet {background: var(--g-color-base-selection); color: var(--g-color-text-brand);}
.green {background: var(--app-green-soft); color: var(--app-green-text);}
.orange {background: var(--app-orange-soft); color: var(--app-orange-text);}
.blue {background: var(--app-blue-soft); color: var(--app-blue-text);}
.pink {background: var(--app-pink-soft); color: var(--app-pink-text);}
.stat-value.g-text {display: block; font-size: 27px; line-height: 34px; font-weight: 600; letter-spacing: -.65px; margin-bottom: var(--g-spacing-3); font-variant-numeric: tabular-nums;}
.stat-bottom {display: flex; align-items: center; gap: var(--g-spacing-2); min-height: 18px; font-size: 9px; color: var(--g-color-text-hint); white-space: nowrap;}
.trend {display: inline-flex; align-items: center; gap: 2px; color: var(--app-green-text); font-weight: 500; font-size: 9px;}
.orange-dot {display: inline-block; width: 5px; height: 5px; background: var(--app-orange-text); border-radius: 50%; margin-right: var(--g-spacing-2);}
.orders-panel {border: 1px solid var(--g-color-line-generic); background: var(--g-color-base-background); border-radius: var(--g-border-radius-l); overflow: hidden; box-shadow: 0 2px 4px var(--g-color-base-generic-ultralight);}
.panel-title {padding: var(--g-spacing-5) var(--g-spacing-5) var(--g-spacing-4); display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-2);}
.panel-title>div {display: flex; align-items: center; gap: var(--g-spacing-2);}
.panel-title .g-text {font-weight: 600; font-size: 15px;}
.count-pill {color: var(--g-color-text-brand); background: var(--g-color-base-selection); padding: 2px var(--g-spacing-2); border-radius: var(--g-border-radius-s); font-size: 10px; font-weight: 550;}
.panel-description {font-size: 10px; color: var(--g-color-text-hint);}
.status-tabs {padding: 0 var(--g-spacing-5); display: flex; gap: var(--g-spacing-5); overflow-x: auto; border-bottom: 1px solid var(--g-color-line-generic); scrollbar-width: none;}
.status-tab.g-button {height: 42px; font-size: 11px; position: relative; border-radius: 0; --g-button-padding: 0; --g-button-background-color-hover: transparent; color: var(--g-color-text-secondary); flex-shrink: 0;}
.status-tab.g-button span:not([class]) {font-size: 9px; display: inline-block; margin-left: var(--g-spacing-2); padding: 1px 5px; border-radius: var(--g-border-radius-s); background: var(--g-color-base-generic-ultralight); color: var(--g-color-text-secondary);}
.status-tab.g-button.active {color: var(--g-color-text-brand); font-weight: 550;}
.status-tab.active::after {position: absolute; content: ''; bottom: 0; left: 0; right: 0; height: 2px; background: var(--g-color-base-brand);}
.status-tab.active.g-button span:not([class]) {background: var(--g-color-base-selection); color: var(--g-color-text-brand);}
.table-toolbar {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); padding: var(--g-spacing-4) var(--g-spacing-5);}
.order-search {width: 310px; max-width: 42%; --g-text-input-border-radius: var(--g-border-radius-m); --g-text-input-border-color: var(--g-color-line-generic); --g-text-input-background-color: var(--g-color-base-background);}
.order-search svg {color: var(--g-color-text-hint); margin-left: var(--g-spacing-1);}
.order-search input {font-size: 10px;}
.toolbar-actions {display: flex; align-items: center; gap: var(--g-spacing-2); flex-shrink: 0;}
.toolbar-actions .g-button {font-size: 10px; height: 32px; --g-button-border-radius: var(--g-border-radius-s); --g-button-border-color: var(--g-color-line-generic);}
.toolbar-actions .g-button svg {color: var(--g-color-text-secondary);}
.toolbar-actions .group-button {color: var(--g-color-text-brand); --g-button-background-color: var(--g-color-base-selection); --g-button-border-color: var(--g-color-base-selection);}
.toolbar-actions .group-button svg {color: var(--g-color-text-brand);}
.toolbar-separator {height: 18px; width: 1px; background: var(--g-color-line-generic); margin: 0 var(--g-spacing-1);}
.filter-dot {display: inline-block; width: 5px; height: 5px; background: var(--g-color-base-brand); border-radius: 50%; margin-left: var(--g-spacing-1);}
.table-scroll {width: 100%; max-height: 502px; min-height: 240px; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--g-color-line-generic) transparent;}
.orders-table {width: 100%; min-width: 1025px; border-spacing: 0; table-layout: fixed;}
.order-th {background: var(--app-surface-soft); color: var(--g-color-text-secondary); font-weight: 450; font-size: 10px; height: 39px; border-top: 1px solid var(--g-color-line-generic); padding: var(--g-spacing-2) var(--g-spacing-3); cursor: grab;}
.order-th:first-child {padding-left: var(--g-spacing-5);}
.order-td {height: 65px; padding: var(--g-spacing-2) var(--g-spacing-3); font-size: 11px; border-color: var(--g-color-line-generic); overflow: hidden;}
.order-td:first-child {padding-left: var(--g-spacing-5);}
.order-row:hover .order-td {background: var(--app-surface-soft);}
.order-row.is-selected .order-td {background: var(--g-color-base-selection);}
.order-th .g-checkbox, .order-td .g-checkbox {--g-checkbox-border-color: var(--g-color-line-generic-accent);}
.order-link.g-button {font-size: 11px; font-weight: 550; color: var(--g-color-text-brand); --g-button-padding: 0; height: 26px;}
.customer {display: flex; align-items: center; gap: var(--g-spacing-3); min-width: 0;}
.avatar {width: 32px; height: 32px; border-radius: 50%; flex-shrink: 0; display: flex; align-items: center; justify-content: center; font-size: 10px; font-weight: 500;}
