.support-content {display: flex; flex-direction: column; align-items: center; text-align: center; gap: var(--g-spacing-4); padding: var(--g-spacing-4) 0;}
.support-icon {display: grid; place-items: center; width: 64px; height: 64px; border-radius: 50%; background: var(--g-color-base-selection); color: var(--g-color-text-brand);}
.support-content p {color: var(--g-color-text-secondary); line-height: 1.8; font-size: 12px; margin: 0;}
.support-content small {color: var(--g-color-text-hint); font-size: 10px;}
.notification-entry {display: flex; gap: var(--g-spacing-4); padding: var(--g-spacing-4) 0; border-bottom: 1px solid var(--g-color-line-generic);}
.notification-entry:last-child {border: none;}
.notification-entry strong {font-size: 12px; font-weight: 550;}
.notification-entry p, .notification-entry small {color: var(--g-color-text-secondary); font-size: 11px;}
.notification-entry .g-button {font-size: 11px; --g-button-padding: 0; color: var(--g-color-text-brand);}
.users-panel, .settings-panel {background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); padding: var(--g-spacing-6);}
.user-list-row {display: flex; align-items: center; gap: var(--g-spacing-5); padding: var(--g-spacing-4) 0; border-bottom: 1px solid var(--g-color-line-generic); font-size: 12px;}
.user-list-row>.customer {flex: 1;}
.user-list-row>span {color: var(--g-color-text-secondary);}
.user-list-row>strong {font-weight: 550; min-width: 100px;}
.settings-panel {max-width: 550px; display: flex; flex-direction: column; gap: var(--g-spacing-5);}
.settings-panel p {font-size: 12px; color: var(--g-color-text-secondary); margin: 0;}
.settings-panel>.g-button {align-self: flex-start;}
@media (min-width: 1550px) {
  .main-content {padding-left: var(--g-spacing-10); padding-right: var(--g-spacing-10);}
  .stat-card {padding: var(--g-spacing-5) var(--g-spacing-6);}
  .table-scroll {max-height: 590px;}
}
@media (max-width: 1200px) {
  .main-content {padding-left: var(--g-spacing-5); padding-right: var(--g-spacing-5);}
  .stat-card {padding: var(--g-spacing-4);}
  .stat-bottom {font-size: 8px; gap: var(--g-spacing-1); flex-wrap: wrap;}
  .stat-value.g-text {font-size: 24px;}
  .table-toolbar {gap: var(--g-spacing-2); padding-left: var(--g-spacing-4); padding-right: var(--g-spacing-4);}
  .order-search {max-width: 36%;}
  .toolbar-actions {gap: var(--g-spacing-1);}
  .panel-description {display: none;}
  .status-tabs {gap: var(--g-spacing-4);}
  .page-badge {display: none;}
}
@media (max-width: 800px) {
  .topbar {padding: 0 var(--g-spacing-5); height: 58px;}
  .main-content {padding-top: var(--g-spacing-5);}
  .stats-grid {grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--g-spacing-3);}
  .stat-card-top {font-size: 11px;}
  .stat-value.g-text {font-size: 25px;}
  .stat-bottom {font-size: 9px;}
  .page-heading {align-items: flex-start; flex-wrap: wrap; margin-bottom: var(--g-spacing-5);}
  .heading-actions {margin-top: var(--g-spacing-1);}
  .table-toolbar {flex-wrap: wrap;}
  .order-search {width: 100%; max-width: none;}
  .toolbar-actions {width: 100%; justify-content: space-between; margin-top: var(--g-spacing-1);}
  .table-scroll {max-height: 500px;}
  .under-table>span:last-child {display: none;}
  .table-footer {flex-wrap: wrap; gap: var(--g-spacing-3);}
  .page-footer {align-items: flex-start; flex-direction: column; gap: var(--g-spacing-1);}
  .live-label, .live-dot {display: none;}
  .topbar-divider {margin: 0 var(--g-spacing-1);}
  .user-list-row {flex-wrap: wrap;}
}
@media (max-width: 480px) {
  .main-content {padding: var(--g-spacing-4) var(--g-spacing-3) 0;}
  .topbar {padding: 0 var(--g-spacing-3);}
  .breadcrumbs {gap: var(--g-spacing-1); font-size: 10px;}
  .breadcrumbs>span {max-width: 112px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;}
  .top-avatar {margin-left: 0; width: 25px; height: 25px; font-size: 9px;}
  .topbar-right {gap: 0;}
  .heading-line .g-text {font-size: 25px;}
  .page-heading p {font-size: 10px; line-height: 1.6;}
  .heading-actions {width: 100%;}
  .heading-actions .g-button {flex: 1; font-size: 10px;}
  .stat-card {padding: var(--g-spacing-3);}
  .stat-icon {width: 25px; height: 25px;}
  .stat-card-top {font-size: 9px; gap: 2px;}
  .stat-icon svg {width: 15px; height: 15px;}
  .stat-value.g-text {font-size: 22px; line-height: 28px;}
  .stat-bottom {font-size: 8px; white-space: normal;}
  .overview-caption {font-size: 10px;}
  .overview-caption>span:last-child {font-size: 8px; gap: var(--g-spacing-1);}
  .status-tabs {padding: 0 var(--g-spacing-3);}
  .table-toolbar {padding: var(--g-spacing-3);}
  .toolbar-actions .g-button {font-size: 9px; --g-button-padding: 6px;}
  .toolbar-separator {display: none;}
  .group-label {display: none;}
  .table-footer {padding: var(--g-spacing-3);}
  .per-page-label {display: none;}
  .pagination-divider {margin: 0 var(--g-spacing-1);}
  .under-table>span {font-size: 8px; line-height: 1.5;}
  .selection-bar {gap: var(--g-spacing-1); padding: var(--g-spacing-2); flex-wrap: wrap;}
  .selection-bar strong {font-size: 10px;}
}
@media (prefers-reduced-motion: reduce) {*, *::before, *::after {scroll-behavior: auto "'!important; transition: none !important; animation: none !important;}}
